const blocks = $input.first().json.content;
const raw = blocks.filter(b => b.type === 'text').map(b => b.text).join('');
const clean = raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1);
const analysis = JSON.parse(clean);
const form = $('Normalize input').first().json;

const cap = s => (s ? s.charAt(0).toUpperCase() + s.slice(1) : s);

return [{
  json: {
    name: form.name,
    email: form.email,
    address: form.address,
    description: form.description,
    source: form.source,
    ...analysis,
    job_type: cap(analysis.job_type)
  }
}];

const analysis = $('Parse AI response').first().json;
const prices = {};
for (const row of $input.all()) {
  prices[row.json.item_id] = row.json;
}

const lines = [];
const unknown = [];
let total = 0;

for (const item of analysis.items) {
  const p = prices[item.item_id];
  if (!p) {
    unknown.push(item.item_id);
    continue;
  }
  const lineTotal = Math.round(item.quantity * Number(p.price_eur) * 100) / 100;
  total += lineTotal;
  lines.push({
    item_id: item.item_id,
    description: p.description,
    quantity: item.quantity,
    quantity_estimated: p.unit !== 'job' && item.quantity_estimated === true,
    unit: p.unit,
    unit_price: Number(p.price_eur),
    line_total: lineTotal
  });
}

return [{
  json: {
    ...analysis,
    lines,
    unknown_items: unknown,
    total_eur: Math.round(total * 100) / 100,
    needs_review: analysis.confidence < 0.6 || lines.some(l => l.quantity_estimated) || unknown.length > 0
  }
}];

const d = $input.first().json;
const today = new Date().toLocaleDateString('en-GB');
const quoteNo = d.quoteNo || ('SR-' + Date.now().toString().slice(-6));
const eur = n => new Intl.NumberFormat('de-DE', { style: 'currency', currency: 'EUR' }).format(n);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const unitLabel = u => ({ m2: 'm²', piece: 'pcs', job: 'job', m: 'm' }[u] || u);

const hasEstimates = d.lines.some(l => l.quantity_estimated);

const rows = d.lines.map(l => `
