    <td class="r">${eur(l.unit_price)}</td>
    <td class="r">${eur(l.line_total)}</td>
  </tr>`).join('');

const html = `<!DOCTYPE html>
<html><head><meta charset="utf-8">
<style>
  body { font-family: Arial, sans-serif; color: #1f2937; margin: 40px; font-size: 13px; }
  .head { display: flex; justify-content: space-between; border-bottom: 3px solid #c2410c; padding-bottom: 14px; }
  h1 { margin: 0; color: #c2410c; font-size: 26px; }
  h2 { font-size: 14px; margin: 26px 0 6px; text-transform: uppercase; color: #6b7280; }
  table { width: 100%; border-collapse: collapse; margin-top: 8px; }
  th { text-align: left; background: #f3f4f6; padding: 8px; }
  td { padding: 8px; border-bottom: 1px solid #e5e7eb; }
  .r { text-align: right; }
  .est { color: #c2410c; font-weight: bold; }
  .legend { margin-top: 6px; font-size: 11px; color: #6b7280; }
  .total { text-align: right; font-size: 18px; font-weight: bold; margin-top: 16px; }
  .note { margin-top: 30px; padding: 12px; background: #fff7ed; border-left: 4px solid #c2410c; font-size: 12px; }
</style></head><body>
  <div class="head">
    <div><h1>Summit Roofing</h1><div>Roofing &amp; Gutter Specialists</div></div>
    <div style="text-align:right">Quote ${quoteNo}<br>${today}</div>
  </div>
  <h2>Prepared for</h2>
  <div>${esc(d.name)}<br>${esc(d.address)}<br>${esc(d.email)}</div>
  <h2>Job summary</h2>
  <div>${esc(d.job_type)}</div>
  <h2>Quote details</h2>
