return [{
  json: { ...q, owner_note: form['Note to customer'] || '', status: 'Sent' },
  binary: $('Generate PDF').first().binary
}];

const base = $('Build quote HTML').first().json;
const resp = $('Owner approval').first().json;
const form = resp.data ?? resp;

const prices = {};
for (const row of $('Get price list').all()) prices[row.json.item_id] = row.json;

const qty = {};
for (const l of base.lines) qty[l.item_id] = { quantity: l.quantity, estimated: l.quantity_estimated };

const invalid = [];
for (const part of String(form['Quantity corrections'] ?? '').split(/[,;\n]+/)) {
  const p = part.trim();
  if (!p) continue;
  const m = p.match(/^([a-z_]+)\s*=\s*(\d+(?:[.,]\d+)?)$/i);
  if (!m || !prices[m[1]]) { invalid.push(p); continue; }
  qty[m[1]] = { quantity: Number(m[2].replace(',', '.')), estimated: false };
}
if (invalid.length) throw new Error('Invalid corrections: ' + invalid.join(', '));

const lines = [];
let total = 0;
for (const [item_id, q] of Object.entries(qty)) {
  if (q.quantity <= 0) continue;
  const p = prices[item_id];
  const lineTotal = Math.round(q.quantity * Number(p.price_eur) * 100) / 100;
  total += lineTotal;
  lines.push({
    item_id,
    description: p.description,
    quantity: q.quantity,
    quantity_estimated: q.estimated,
    unit: p.unit,
    unit_price: Number(p.price_eur),
    line_total: lineTotal
  });
}

return [{
  json: {
    ...base,
    lines,
    total_eur: Math.round(total * 100) / 100,
    owner_note: form['Note to customer'] || ''
  }
}];

