const item = $input.first();
const j = item.json;
const b = j.body ?? j;

const pick = (...keys) => {
  for (const k of keys) {
    if (b[k] !== undefined && b[k] !== null && b[k] !== '') return String(b[k]);
  }
  return '';
};

const data = {
  name: pick('Name', 'name'),
  email: pick('Email', 'email'),
  address: pick('Address', 'address'),
  description: pick('Job description', 'job_description'),
  source: j.body ? 'email' : 'form'
};

const bin = item.binary || {};
const firstKey = Object.keys(bin)[0];
if (!firstKey) throw new Error('No roof photo received');

return [{ json: data, binary: { photo: bin[firstKey] } }];
